
prompts = {}

# Function to retrieve prompts dynamically
def get_prompt(name: str) -> str:
    """
    Retrieve a prompt by its variable name.
    Raises KeyError if not found.
    """
    try:
        return prompts[name]
    except KeyError:
        raise KeyError(f"Prompt '{name}' not found.")

